register_success.html.html:
{% extends "base.html" %}
{% block title %}Регистрация успешна{% endblock %}

{% block content %}
<h1>Добро пожаловать, {{ user.login }}!</h1>
<div class="card center">
  <p class="ok-text">«Бо-о-о-о! Теперь ты в моей коллекции, пилот!»</p>
  <p>Регистрация прошла успешно — аккаунт создан, и вы уже авторизованы.</p>

  <img src="{{ url_for('static', filename='gifs/welcome.gif') }}"
       alt="Welcome"
       style="display:block;max-width:320px;width:100%;margin:18px auto;border-radius:12px;box-shadow:0 0 24px rgba(255,232,31,.35);">

  <a class="btn primary" href="{{ url_for('account') }}">Перейти в личный кабинет</a>
</div>
{% endblock %}

files.html.html:
{% extends "base.html" %}
{% block title %}Мои файлы — TXT Cloud{% endblock %}

{% block content %}
<h1>Мои файлы</h1>

<div class="card">
  <h2>📁 Ваш txt-файл</h2>
  {% if has_note %}
    <p class="ok-text">Файл загружен и готов к чтению.</p>
    <div class="actions">
      <a class="btn" href="{{ url_for('read') }}">Прочитать файл</a>
      <a class="btn" href="{{ url_for('upload') }}">Заменить файл</a>
    </div>
  {% else %}
    <p class="muted">Файл ещё не загружен.</p>
    <a class="btn primary" href="{{ url_for('upload') }}">Загрузить файл</a>
  {% endif %}
</div>

<div class="card">
  <h2>🚀 Развлечение</h2>
  <p class="muted">Сыграйте в Hyperspace Defender, пока Империя не видит.</p>
  <a class="btn" href="{{ url_for('game') }}">Играть</a>
</div>
{% endblock %}

